from collections import deque

def bfs(graf, start):
    odleglosc = {start: 0}
    kolejka = deque([start])
    while kolejka:
        u = kolejka.popleft()          # deque -> BFS; pop() dałoby DFS
        for v in graf[u]:
            if v not in odleglosc:     # oznacz W MOMENCIE dodania do kolejki
                odleglosc[v] = odleglosc[u] + 1
                kolejka.append(v)
    return odleglosc
